// Shared bits for every page: header, footer, site.json + releases.json loading and a tiny markdown renderer.
// Generated by apkship. Everything specific to the app comes from site.json, so this file rarely needs editing.
(function () {
  var here = (location.pathname.split("/").pop() || "index.html").toLowerCase();
  var NAV = [["index.html", "Home"], ["features.html", "Features"], ["tips.html", "Tips"], ["install.html", "Install"], ["changelog.html", "Changelog"], ["about.html", "About"]];

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; });
  }

  function load(file) {
    return fetch(file, { cache: "no-store" }).then(function (r) { if (!r.ok) throw new Error(file + " " + r.status); return r.json(); });
  }

  var S = {
    esc: esc,
    site: null,
    fmtSize: function (n) { return (n / 1048576).toFixed(n > 10485760 ? 0 : 1) + " MB"; },
    fmtDate: function (s) { try { return new Date(s).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" }); } catch (e) { return ""; } },
    releases: function () {
      if (!window.__rel) window.__rel = load("releases.json").then(function (d) { return d.releases || []; });
      return window.__rel;
    },
    // very small markdown: ## / ### headings, - lists, **bold**, `code`, [links](url), paragraphs
    md: function (src) {
      function inline(t) {
        return esc(t)
          .replace(/`([^`]+)`/g, "<code>$1</code>")
          .replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>")
          .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2" rel="noopener">$1</a>');
      }
      var out = [], list = false, para = [];
      function flush() { if (para.length) { out.push("<p>" + inline(para.join(" ")) + "</p>"); para = []; } }
      function close() { if (list) { out.push("</ul>"); list = false; } }
      String(src || "").split(/\r?\n/).forEach(function (line) {
        var m;
        if ((m = line.match(/^#{1,2}\s+(.*)/)) && !/^#{3}/.test(line)) { flush(); close(); return; } // the release title is shown separately
        if ((m = line.match(/^#{3,4}\s+(.*)/))) { flush(); close(); out.push("<h3>" + inline(m[1]) + "</h3>"); return; }
        if ((m = line.match(/^\s*[-*]\s+(.*)/))) { flush(); if (!list) { out.push("<ul>"); list = true; } out.push("<li>" + inline(m[1]) + "</li>"); return; }
        if (!line.trim()) { flush(); close(); return; }
        if (list && /^\s{2,}\S/.test(line)) { out[out.length - 1] = out[out.length - 1].replace(/<\/li>$/, " " + inline(line.trim()) + "</li>"); return; }
        close(); para.push(line.trim());
      });
      flush(); close();
      return out.join("");
    },
    copyButtons: function (root) {
      (root || document).querySelectorAll("button.copy").forEach(function (b) {
        b.addEventListener("click", function () { navigator.clipboard && navigator.clipboard.writeText(b.dataset.h); b.textContent = "copied"; setTimeout(function () { b.textContent = "copy"; }, 1200); });
      });
    },
  };

  S.ready = load("site.json").then(function (site) {
    S.site = site;
    S.REPO = site.repo;
    if (site.themeColor) document.documentElement.style.setProperty("--accent", site.themeColor);
    var head = document.getElementById("site-header");
    if (head) {
      head.className = "top";
      head.innerHTML =
        '<div class="wrap"><a class="brand" href="index.html"><span class="mark">' + esc(site.icon) + "</span> " + esc(site.name) + "</a>" +
        '<button class="menu-btn" aria-label="Menu" id="menu-btn">&#9776;</button><nav class="main" id="main-nav">' +
        NAV.map(function (p) { return '<a href="' + p[0] + '"' + (here === p[0] ? ' class="on"' : "") + ">" + p[1] + "</a>"; }).join("") +
        '<a href="play/" class="play">▶ Play</a><a class="dl" href="install.html#download">Download</a></nav></div>';
      document.getElementById("menu-btn").addEventListener("click", function () { document.getElementById("main-nav").classList.toggle("open"); });
    }
    var foot = document.getElementById("site-footer");
    if (foot) {
      var extra = (site.links || []).map(function (l) { return '<a href="' + esc(l.href) + '">' + esc(l.label) + "</a>"; }).join("");
      foot.innerHTML =
        '<div class="wrap"><div class="cols"><div><b style="color:var(--text)">' + esc(site.name) + "</b><br>" + esc(site.tagline) + "</div>" +
        '<div class="links"><a href="features.html">Features</a><a href="tips.html">Tips &amp; tricks</a><a href="install.html">Install</a><a href="changelog.html">Changelog</a><a href="about.html">About</a>' + extra + "</div>" +
        '<div class="links"><a href="' + esc(site.repo) + '/releases">All releases on GitHub</a><a href="' + esc(site.repo) + '/issues">Report a problem</a><a href="releases.json">releases.json</a></div></div></div>';
    }
    return site;
  });

  window.Site = S;
})();

// tap any screenshot to see it full size
document.addEventListener("click", function (e) {
  var f = e.target.closest && e.target.closest(".shot img, .phone img");
  var lb = document.getElementById("lb");
  if (lb && lb.classList.contains("on")) { lb.classList.remove("on"); return; }
  if (!f) return;
  if (!lb) { lb = document.createElement("div"); lb.id = "lb"; lb.innerHTML = "<img alt=\"\">"; document.body.appendChild(lb); }
  lb.firstChild.src = f.src; lb.firstChild.alt = f.alt; lb.classList.add("on");
});
document.addEventListener("keydown", function (e) { var lb = document.getElementById("lb"); if (e.key === "Escape" && lb) lb.classList.remove("on"); });
